#include <stdlib.h>
typedef struct Node { int v; struct Node *next; } Node;
int main(void) {
    Node *top = NULL;
    int vals[] = {3, 7, 5};
    for (int i = 0; i < 3; i++) {
        Node *n = malloc(sizeof(Node));
        n->v = vals[i]; n->next = top; top = n;
    }
    printf("%d\n", top->v);
}

