#include <stdio.h>
int main(void) {
    char *p = "231*+9-";
    int st[8], top = -1;
    for (int i = 0; p[i]; i++) {
        if (p[i] >= '0' && p[i] <= '9') { st[++top] = p[i] - '0'; continue; }
        int b = st[top--]; int a = st[top--];
        st[++top] = p[i] == '+' ? a + b : (p[i] == '*' ? a * b : a - b);
    }
    printf("%d\n", st[top]);
    return 0;
}

