    top--; top--;
    if (top < 0) printf("empty\n");
    else printf("%d\n", st[top]);
    return 0;
}

#include <stdio.h>
int main(void) {
    char *s = "(())()";
    int depth = 0, max = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] == '(') depth++;
        else depth--;
        if (depth > max) max = depth;
    }
    printf("%d %d\n", depth, max);
}
